INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9ebf-c0f9-7dd7-b923-9fb7158d1938'::uuid, '019f9df7-a2a2-78ab-b1d6-52be9d287151'::uuid, 'ABC is part of a polygon and the interior angle at A is 148°. The remaining interior angles are each 139°. Find the number of sides of the polygon.', '9', 'Let the polygon have n sides. One interior angle is 148° and the other (n − 1) interior angles are each 139°. So 148 + (n − 1) × 139 = (n − 2) × 180. Solving gives n = 9.', 'Medium', '{"tags":"angles,polygons,interior-angles","subtopic":"polygons","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T14:06:34.745Z'::timestamptz, '2026-07-26T14:06:34.745Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019fa42c-3501-7dcf-ba5e-66f75d786ca0'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'Expand and simplify the expression (4x - 3)(5 + 2x) - (3x - 1)^2.', '-x^2 + 20x - 16', '(4x - 3)(5 + 2x) = 20x + 8x^2 - 15 - 6x = 8x^2 + 14x - 15.
(3x - 1)^2 = 9x^2 - 6x + 1.
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019fa42c-3506-742e-b0e4-dfa63c5814a4'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, '(a) Express 3150 as a product of its prime factors in index notation.
(b) Given that 1260 = 2^2 × 3^2 × 5 × 7, find:
(i) the highest common factor (HCF) of 3150 and 1260,
(ii) the smallest positive integer k such that 3150k is a perfect cube.', '(a) 2 × 3^2 × 5^2 × 7
(b)(i) 630
(b)(ii) 2940', '(a) Prime factorisation of 3150 = 2 × 3^2 × 5^2 × 7.
(b)(i) HCF = 2^1 × 3^2 × 5^1 × 7^1 = 630.
(b)(ii) For 3150k to be a perfect cube, powers of prime factors must be multiples of 3.
